"""Explain word wrappers, empty inputs and verification scope."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1937': ('재료를 준비하는 사람과 섞는 사람의 역할이 나뉘어 있어요. 섞는 사람이 이미 준비된 양념을 받는데 또 같은 양념을 넣으면 결과가 달라져요.', '공개 wrapper와 내부 helper의 초기값 준비 책임을 구분합니다.', '고정 상수 K·seed 7·세 항목 길이 12를 합쳐 K+19를 만들고 내부 함수에 전달한다고 적으세요.', ['__jhash_nwords는 a·b·c 세 정수에 전달받은 initval을 각각 더하고 final로 섞은 뒤 c를 반환하는 내부 함수예요. helper는 다른 함수의 일을 돕는 작은 함수라는 뜻이에요. 이 함수는 고정 상수나 입력 길이를 스스로 계산하지 않아요.', 'jhash_3words는 이 내부 함수를 감싸는 wrapper예요. wrapper는 호출자가 쓰기 편하도록 필요한 준비를 대신하는 함수예요. 여기서는 사용자가 준 seed에 JHASH_INITVAL과 세 항목의 바이트 길이 12를 더해 내부 initval로 넘겨요.', '같은 initval이라는 이름이 보이지만 호출 단계에 따라 담긴 내용이 달라요. 바깥 함수의 initval은 사용자가 준 시작값이고, 내부 함수에 전달할 때는 고정 상수와 길이를 이미 더한 준비된 값이에요.', '고정 상수를 K로 적고 사용자의 seed가 7이라면 세 항목 wrapper는 7+K+12, 즉 K+19를 전달해요. 내부 함수는 a·b·c에 그 값을 각각 더해요. 원래 입력 a를 길이 12로 덮어쓰는 방식이 아니에요.', '내부 helper를 직접 비교 계산할 때 seed 7만 넣으면 wrapper가 준비하는 K와 12가 빠져 시작 상태가 달라져요. 반대로 준비된 값에 K와 길이를 또 더해도 틀려요. 어느 단계가 무엇을 더하는지 한 번씩 확인해야 해요.', '실제 식은 u32의 32비트 순환 계산 규칙을 따라요. 여기서 K+19 표기는 책임 분담을 쉽게 보는 표현이에요. 내부 함수와 바깥 함수의 결과를 맞추려면 입력 값뿐 아니라 준비된 초기값도 같게 해야 해요.'], [('내부 __jhash_nwords가 JHASH_INITVAL을 직접 계산해 추가하나요?', ['네. 스스로 언제나 두 번 추가해요', '아니요. 바깥 wrapper가 포함해 전달해요'], '정답은 두 번째예요. 내부 본문에는 a·b·c에 initval을 더하는 코드만 있어요. 고정 상수와 길이 준비는 wrapper의 식에 있어요.'), ('내부 helper를 세 항목 wrapper와 같은 조건으로 계산하려면 길이 12를 어디에 포함하나요?', ['내부로 전달할 initval에 seed와 고정 상수와 함께 더해요', '입력의 첫 정수 값을 12로 덮어써요'], '정답은 첫 번째예요. 입력 자료와 초기 계산 매개값은 역할이 달라요. 입력 자체를 고치면 같은 자료를 계산하는 비교가 아니게 돼요.')]), 'os1938': ('물건 한 개·두 개·세 개를 위한 작은 접수 창구가 따로 있어요. 적은 수의 정수는 배열을 따로 준비하지 않고 바로 함수에 줄 수 있어요.', '고정 개수 wrapper의 빈 자리와 바이트 길이를 이해합니다.', '한 항목은 (a,0,0)과 길이 4, 두 항목은 (a,b,0)과 길이 8, 세 항목은 (a,b,c)와 길이 12를 짝지으세요.', ['jhash_1word·jhash_2words·jhash_3words는 각각 u32 정수 한 개·두 개·세 개를 받는 함수예요. 여기서 word는 u32 하나이며 4바이트예요. 적은 입력 값을 이미 가지고 있다면 이를 임시 배열로 만들지 않고 직접 전달할 수 있어요.', '한 항목 함수는 내부 helper에 a·0·0을 넘겨요. 두 항목 함수는 a·b·0을 넘기고 세 항목 함수는 a·b·c를 넘겨요. 입력에 없는 자리를 0으로 채우는 약속이에요. 두 항목일 때 c에 b를 한 번 더 복제하는 것이 아니에요.', '길이 계산은 별도로 해요. 한 항목이면 1×4=4바이트, 두 항목이면 8바이트, 세 항목이면 12바이트를 seed와 고정 상수에 더해요. 코드의 1<<2·2<<2·3<<2는 각각 이 4배 계산을 나타내요.', '두 항목 [10,20]이면 내부의 자료 인수는 10·20·0이에요. 마지막 0을 넣었다고 실제 입력 길이를 세 항목인 12바이트로 계산하지 않아요. 길이는 여전히 두 항목의 8바이트예요. 빈 자리 채우기와 실제 길이 정보를 구별하세요.', 'C는 여기서 정수 값을 복사해서 함수 인수로 넘겨요. 내부의 a·b·c가 바뀌어도 호출한 쪽의 정수 변수나 배열을 직접 수정하는 것은 아니에요. 반환된 hash 값을 받아 사용해요.', '같은 정수 값과 seed로 같은 길이의 jhash2를 계산하면 이 wrapper들과 같은 초기 상태와 마지막 섞기를 구성할 수 있어요. 바이트 배열을 읽는 jhash와 비교할 때는 메모리의 바이트 순서도 고려해야 하므로 모든 기종에서 무조건 같다고 넓혀 설명하지 않아요.'], [('jhash_2words가 내부 helper의 c 자리에 넘기는 값은 무엇인가요?', ['b를 그대로 한 번 더 복제해요', '0이에요'], '정답은 두 번째예요. 두 입력은 a와 b이고 비어 있는 c 자리는 0이에요. 실제 입력 길이는 두 u32의 8바이트로 따로 반영해요.'), ('jhash_3words가 초기값에 반영하는 입력 바이트 길이는 얼마인가요?', ['12바이트예요', '3바이트예요'], '정답은 첫 번째예요. u32 한 개가 4바이트이므로 세 개는 3×4=12바이트예요. 항목 개수 3과 바이트 크기 12를 구분하세요.')]), 'os1939': ('아무 카드도 읽지 않더라도 계산의 출발 숫자는 남아 있어요. 빈 입력의 결과가 반드시 숫자 0일 필요는 없어요.', '길이 0일 때 읽기 생략과 초기값 반환을 이해합니다.', '길이 0 → 반복 생략 → case 0 → 초기 c 반환을 그리세요. 길이 1에는 k[0] 읽기가 생긴다고 옆에 적으세요.', ['jhash와 jhash2는 길이가 0이어도 초기 상태 a·b·c를 먼저 계산해요. 고정 상수 JHASH_INITVAL에 seed를 더한 값이에요. 길이에서 오는 덧셈은 0이지만 고정 상수와 seed가 없어지는 것은 아니에요.', '길이 0은 반복 조건을 만족하지 않아요. 마지막 switch도 case 0으로 가서 final을 호출하지 않고 나와요. 따라서 마지막 return c는 섞기 전 초기값을 그대로 반환해요.', 'seed가 0이면 빈 입력의 결과는 0xdeadbeef예요. 0x는 16진수 표기라는 뜻이에요. seed가 7이면 0xdeadbef6이고, 덧셈이 u32 범위를 넘는 경우에는 32비트 규칙대로 순환해요.', '이 두 함수의 길이 0 경로는 입력 항목을 읽지 않아요. NULL은 유효한 자료 주소를 가리키지 않는 표시인데, 이 경로에서 NULL을 전달해도 자료를 역참조하는 연산이 없다는 점을 코드로 확인할 수 있어요. 이를 모든 함수의 NULL 허용 규칙으로 일반화하지 않아요.', '길이 1이면 상황이 달라요. case 1에서 k[0]을 읽으므로 실제로 읽을 수 있는 입력 주소가 필요해요. 길이 0 사례가 괜찮았다는 이유로 NULL과 양수 길이를 함께 넘기면 안 돼요. 읽을 개수만큼 자료가 존재해야 해요.', '여기서 반환값은 검색용 hash예요. stack depot에서 번호 0을 실패 표시로 쓰는 규칙과 다른 함수의 약속이에요. 해시값이 0이라고 그 자체가 반드시 오류인 것도 아니고, 입력이 비었다고 해시값이 반드시 0인 것도 아니에요.'], [('jhash의 길이가 0이고 seed도 0이면 반환값은 무엇인가요?', ['언제나 0이에요', '0xdeadbeef예요'], '정답은 두 번째예요. 초기 c에 고정 상수가 들어가고 빈 분기는 추가 섞기 없이 반환해요. 빈 입력이라는 이유만으로 초기 상수가 사라지지는 않아요.'), ('NULL·길이 0인 경로에서 읽기가 없으면 NULL·길이 1도 안전한가요?', ['아니요. 길이 1에는 실제 입력 읽기가 생겨요', '네. NULL은 길이와 관계없이 언제나 안전해요'], '정답은 첫 번째예요. 길이 1은 k[0]을 읽어야 해요. 자료를 읽지 않는 분기의 조건을 읽는 분기까지 확대하면 안 돼요.')]), 'os1940': ('계산기 답이 맞는지 검사하는 것과 얼마나 빠른지 재는 것은 다른 시험이에요. 해시도 검사마다 답하려는 질문을 나눠야 해요.', '결과 대조와 분포 관찰, 호출 시스템 검증의 범위를 구분합니다.', '정답 일치·바뀐 비트 수·실행 시간·동시 사용 안전을 네 칸에 쓰고 서로 다른 질문이라고 표시하세요.', ['reference는 결과를 비교할 기준 계산을 뜻해요. test vector는 입력과 그 입력에서 기대하는 결과를 묶은 사례예요. 같은 입력을 C 구현과 별도의 기준 계산에 넣어 결과가 맞는지 확인하면 선택한 사례의 계산 일치를 검사할 수 있어요.', '기준을 Python으로 만들 때는 Python 정수가 커질 수 있다는 차이를 반영해야 해요. 원문의 u32 상태는 32비트 범위로 순환하므로 필요한 연산 뒤 아래 32비트만 남겨요. 숫자가 무한히 커지는 계산을 그대로 쓰면 다른 알고리즘을 비교하는 셈이에요.', '마지막 바이트 처리는 C의 switch를 글자 그대로 복사하는 대신 각 바이트의 번호로 어느 상태와 어느 비트 위치에 더할지 계산할 수도 있어요. 같은 실수를 양쪽에 복제할 가능성을 줄이는 방법이에요. 그래도 기준 계산 자체가 틀릴 수 있으므로 코드 일치만으로 모든 입력을 증명했다고 하지는 않아요.', '입력 한 비트를 바꿔 출력의 몇 비트가 달라지는지 세는 것은 변화의 퍼짐을 관찰하는 시험이에요. 정확한 기대값과 같은지 대조하는 시험과 질문이 달라요. 빠르게 계산하는지, 충돌이 얼마나 생기는지도 따로 조건을 정해 관찰해야 해요.', '해시 helper의 결과가 맞아도 이를 쓰는 stack depot 전체가 자동으로 검증되는 것은 아니에요. 저장소는 같은 hash의 실제 내용을 비교해야 하고, 메모리를 얻고 돌려주며, 여러 실행이 함께 접근할 때 자료 수명을 지켜야 해요. helper 결과 대조는 이런 모든 작업을 대신 시험하지 않아요.', '기존 자료의 사례 수나 평균 수치를 볼 때는 어떤 입력·길이·바이트 순서에서 실행했는지와 결과 기록을 함께 봐요. 이 수업의 설명을 읽는 것 자체가 그 과거 시험을 다시 실행한 것은 아니에요. 무엇을 확인했고 무엇은 아직 확인하지 않았는지 구별하는 습관을 익혀요.'], [('정확한 기대 hash와의 일치, 선택 입력의 비트 변화 분포는 같은 것을 증명하나요?', ['네. 한 번 검사하면 모든 성질이 증명돼요', '아니요. 각각 확인하려는 질문과 범위가 달라요'], '정답은 두 번째예요. 기대값 대조는 선택 사례의 계산을, 비트 변화 관찰은 선택한 변화의 퍼짐을 봐요. 전체 입력의 충돌이나 성능까지 한꺼번에 증명하지 않아요.'), ('해시 header의 결과를 대조하면 stack depot의 모든 동시 실행도 검증되나요?', ['아니요. 자료 수명과 메모리 관리 등은 별도로 확인해야 해요', '네. RCU와 할당기 동작까지 모두 증명돼요'], '정답은 첫 번째예요. hash는 저장소가 사용하는 한 부품이에요. 부품 계산이 맞는다는 증거와 여러 실행이 안전하게 부품을 사용하는 증거를 구별해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_480.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
